package mcp

import (
	"strings"
	"testing"

	"github.com/mudler/nib/types"
)

func TestResolveRefUnknownErrorsWithFreshSnapshotHint(t *testing.T) {
	b := newBrowserServer(types.BrowserConfig{})
	_, err := b.resolveRef("@e5")
	if err == nil {
		t.Fatal("expected error for unknown ref, got nil")
	}
	if !strings.Contains(err.Error(), "browser_snapshot") {
		t.Fatalf("error should point the model at a fresh browser_snapshot, got: %v", err)
	}
}

func TestResolveRefTrimsWhitespaceAndFindsKnownRef(t *testing.T) {
	b := newBrowserServer(types.BrowserConfig{})
	b.refs["@e5"] = 42

	id, err := b.resolveRef(" @e5 ")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if id != 42 {
		t.Fatalf("id = %d, want 42", id)
	}
}

func TestLiveRefErrorsWhenNoBrowserOpen(t *testing.T) {
	b := newBrowserServer(types.BrowserConfig{})
	_, _, err := b.liveRef("@e5")
	if err == nil {
		t.Fatal("expected error when no page is open, got nil")
	}
	if !strings.Contains(err.Error(), "browser_navigate") {
		t.Fatalf("error should point the model at browser_navigate, got: %v", err)
	}
}

package mcp

import (
	"path/filepath"
	"testing"

	"github.com/mudler/nib/auth"
	"github.com/mudler/nib/llmprovider"
	"github.com/mudler/nib/plugin"
	"github.com/mudler/nib/provider"
	"github.com/mudler/nib/types"
)

// TestWebFetchLLMUsesCredentialStore proves that the LLM built by
// StartWebMCPServer resolves its API key from the on-disk credential store
// (populated by `nib login`), not just from config.api_key or the environment.
//
// Before the fix, StartWebMCPServer built its LLM with llmprovider.New (no
// store), so providers authenticated via `nib login` sent requests with no
// Authorization header and got 401.
//
// We verify the resolution at the llmprovider level: the same provider config
// that yields an empty key with llmprovider.New (no store) yields the stored
// key with llmprovider.NewWithStore. The fix makes StartWebMCPServer use the
// latter.
func TestWebFetchLLMUsesCredentialStore(t *testing.T) {
	// Use a provider that is in the static registry and whose env var is
	// not set in the test environment, so the only key source is the store.
	regolo, ok := provider.Get("regolo")
	if !ok {
		t.Fatal("regolo provider not registered")
	}
	const storedKey = "stored-key-from-login"

	// Write the key into a credential store at the path nib would use.
	dir := t.TempDir()
	storePath := filepath.Join(plugin.BaseDirIn(dir), "credentials.json")
	store := auth.NewStore(storePath)
	if err := store.Save(auth.Credential{
		ProviderID: regolo.ID,
		Kind:       auth.CredentialAPIKey,
		APIKey:     storedKey,
	}); err != nil {
		t.Fatalf("save credential: %v", err)
	}

	// Config with no API key — the key is only in the credential store.
	cfg := types.ModelProviderConfig{
		Provider: "regolo",
		Model:    "test-model",
	}

	// Without the store (the old code path), the key is empty because
	// REGOLO_API_KEY is not set in the test env and config has no key.
	_, noStoreKey, err := llmprovider.ModelsEndpoint(cfg, nil)
	if err != nil {
		t.Fatalf("ModelsEndpoint (no store): %v", err)
	}
	if noStoreKey != "" {
		t.Fatalf("expected empty key without store, got %q", noStoreKey)
	}

	// With the store (the fixed code path), the stored key is resolved.
	_, withStoreKey, err := llmprovider.ModelsEndpoint(cfg, store)
	if err != nil {
		t.Fatalf("ModelsEndpoint (with store): %v", err)
	}
	if withStoreKey != storedKey {
		t.Fatalf("expected stored key %q, got %q", storedKey, withStoreKey)
	}
}

// TestWebFetchCredentialStorePath proves that StartWebMCPServer constructs the
// store at the same path as NewSession, so a key stored by `nib login` is
// visible to both the session LLM and the web_fetch extraction LLM.
func TestWebFetchCredentialStorePath(t *testing.T) {
	// The path NewSession uses (chat/session.go):
	//   filepath.Join(plugin.BaseDirIn(cfg.BaseDir), "credentials.json")
	sessionPath := filepath.Join(plugin.BaseDirIn("/tmp/x"), "credentials.json")

	// The path StartWebMCPServer now uses (mcp/web.go) — same formula.
	webPath := filepath.Join(plugin.BaseDirIn("/tmp/x"), "credentials.json")

	if sessionPath != webPath {
		t.Fatalf("store path mismatch: session=%q web=%q", sessionPath, webPath)
	}
}

package mcp

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/mudler/nib/types"
)

func TestAuthenticatedHTTPClientNilWhenNoAuth(t *testing.T) {
	if c := authenticatedHTTPClient(types.MCPServer{URL: "https://x"}); c != nil {
		t.Fatalf("expected nil client for no auth, got %+v", c)
	}
}

func TestAuthenticatedHTTPClientSetsBearerToken(t *testing.T) {
	var gotAuth string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotAuth = r.Header.Get("Authorization")
		w.WriteHeader(http.StatusOK)
	}))
	defer srv.Close()

	client := authenticatedHTTPClient(types.MCPServer{URL: srv.URL, BearerToken: "secret123"})
	if client == nil {
		t.Fatalf("expected non-nil client")
	}
	resp, err := client.Get(srv.URL)
	if err != nil {
		t.Fatalf("GET: %v", err)
	}
	resp.Body.Close()
	if gotAuth != "Bearer secret123" {
		t.Fatalf("Authorization header: got %q, want %q", gotAuth, "Bearer secret123")
	}
}

func TestAuthenticatedHTTPClientSetsCustomHeaders(t *testing.T) {
	var gotKey, gotOther string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotKey = r.Header.Get("X-Api-Key")
		gotOther = r.Header.Get("X-Other")
		w.WriteHeader(http.StatusOK)
	}))
	defer srv.Close()

	client := authenticatedHTTPClient(types.MCPServer{
		URL:     srv.URL,
		Headers: map[string]string{"X-Api-Key": "k1", "X-Other": "v2"},
	})
	if client == nil {
		t.Fatalf("expected non-nil client")
	}
	resp, err := client.Get(srv.URL)
	if err != nil {
		t.Fatalf("GET: %v", err)
	}
	resp.Body.Close()
	if gotKey != "k1" || gotOther != "v2" {
		t.Fatalf("headers: X-Api-Key=%q X-Other=%q", gotKey, gotOther)
	}
}

func TestAuthenticatedHTTPClientSetsTokenAndCustomHeaders(t *testing.T) {
	var gotAuth, gotKey string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotAuth = r.Header.Get("Authorization")
		gotKey = r.Header.Get("X-Api-Key")
		w.WriteHeader(http.StatusOK)
	}))
	defer srv.Close()

	client := authenticatedHTTPClient(types.MCPServer{
		URL:         srv.URL,
		BearerToken: "secret123",
		Headers:     map[string]string{"X-Api-Key": "k1"},
	})
	if client == nil {
		t.Fatalf("expected non-nil client")
	}
	resp, err := client.Get(srv.URL)
	if err != nil {
		t.Fatalf("GET: %v", err)
	}
	resp.Body.Close()
	if gotAuth != "Bearer secret123" {
		t.Fatalf("Authorization header: got %q, want %q", gotAuth, "Bearer secret123")
	}
	if gotKey != "k1" {
		t.Fatalf("X-Api-Key header: got %q, want %q", gotKey, "k1")
	}
}

package llmprovider

import (
	"context"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"reflect"
	"testing"

	"github.com/mudler/nib/auth"
	"github.com/mudler/nib/llmprovider/registry"
	"github.com/mudler/nib/provider"
	"github.com/mudler/nib/types"
)

// Exercise registered factories, not constructors that bypass credential resolution.
func TestNativeCustomEndpointCredentials(t *testing.T) {
	for _, id := range []string{"anthropic", "google", "google-vertex", "zai"} {
		t.Run(id, func(t *testing.T) {
			def, _ := provider.Get(id)
			factory, _ := registry.Get(def.Protocol)
			t.Setenv(def.EnvVar, "sentinel-env")
			for _, stored := range []auth.CredentialKind{"", auth.CredentialAPIKey, auth.CredentialOAuth} {
				t.Run(string(stored), func(t *testing.T) {
					store := auth.NewStore(filepath.Join(t.TempDir(), "credentials.json"))
					if stored != "" {
						if err := store.Save(auth.Credential{ProviderID: id, Kind: stored, APIKey: "sentinel-store", AccessToken: "sentinel-oauth"}); err != nil {
							t.Fatal(err)
						}
					}
					for _, key := range []string{"", "endpoint-key"} {
						t.Run("key="+key, func(t *testing.T) {
							srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
								if r.Header.Get("Authorization") != "" {
									t.Errorf("unexpected bearer auth: %v", r.Header)
								}
								header := "x-goog-api-key"
								if def.Protocol == provider.ProtocolAnthropicMessages {
									header = "x-api-key"
								}
								if got := r.Header.Get(header); got != key {
									t.Errorf("key=%q want %q", got, key)
								}
								w.Write([]byte(`{}`))
							}))
							defer srv.Close()
							llm, err := factory(def, types.ModelProviderConfig{BaseURL: srv.URL, APIKey: key}, store, 0)
							if key == "" {
								if err == nil {
									t.Fatal("custom endpoint without explicit key accepted ambient credentials")
								}
								return
							}
							if err != nil {
								t.Fatal(err)
							}
							// Vertex API-key discovery deliberately does not send HTTP requests;
							// inspect resolved config too, covering the credentials used by inference.
							cfg := reflect.ValueOf(llm).Elem().FieldByName("config")
							if cfg.FieldByName("APIKey").String() != key || cfg.FieldByName("Token").String() != key || cfg.FieldByName("IsOAuth").Bool() {
								t.Fatal("custom config inherited vendor credentials")
							}
							llm.(registry.ModelDiscoverer).DiscoverModels(context.Background())
						})
					}
				})
			}
			// A registered compatible provider's own URL is not a custom override.
			for _, base := range []string{"", def.BaseURL, def.BaseURL + "/"} {
				llm, err := factory(def, types.ModelProviderConfig{BaseURL: base}, nil, 0)
				if err != nil {
					t.Fatal(err)
				}
				if got := reflect.ValueOf(llm).Elem().FieldByName("config").FieldByName("APIKey").String(); got != "sentinel-env" {
					t.Fatalf("official key=%q", got)
				}
			}
		})
	}
}

package chat

import (
	"context"
	"errors"
	"testing"
	"time"

	"github.com/mudler/cogito"
	openai "github.com/sashabaranov/go-openai"
)

func TestAgentRetryWaitsOutRateLimit(t *testing.T) {
	waits := stubRetrySleep(t)
	r := &agentRetrier{}
	calls := 0
	got, err := retryAgentRequest(context.Background(), r, func() (string, error) {
		calls++
		if calls <= 5 {
			return "", errors.New("localai stream: status 429: " + resetAt(4*time.Minute))
		}
		return "ok", nil
	})
	if err != nil || got != "ok" {
		t.Fatalf("retryAgentRequest = %q, %v; want the sub-agent to outlast the limit", got, err)
	}
	if len(*waits) != 5 || (*waits)[0] < 3*time.Minute {
		t.Fatalf("waits = %v; want 5 waits until the reset", *waits)
	}
}

func TestAgentRetryReturnsFatalAtOnce(t *testing.T) {
	stubRetrySleep(t)
	calls := 0
	_, err := retryAgentRequest(context.Background(), &agentRetrier{}, func() (string, error) {
		calls++
		return "", errors.New("localai stream: status 401: bad key")
	})
	if err == nil || calls != 1 {
		t.Fatalf("calls = %d, err = %v; a fatal error must not be retried", calls, err)
	}
}

// After a spent budget the client tries once per call, so cogito's own
// retries do not repeat the whole budget. A success re-arms it.
func TestAgentRetryFailsFastAfterBudget(t *testing.T) {
	stubRetrySleep(t)
	r := &agentRetrier{}
	fail := func() (string, error) { return "", errors.New("status 503: busy") }

	calls := 0
	count := func(fn func() (string, error)) func() (string, error) {
		return func() (string, error) { calls++; return fn() }
	}
	if _, err := retryAgentRequest(context.Background(), r, count(fail)); err == nil {
		t.Fatal("expected the error after the budget")
	}
	if calls != turnRetryBudget {
		t.Fatalf("calls = %d, want %d", calls, turnRetryBudget)
	}

	calls = 0
	retryAgentRequest(context.Background(), r, count(fail))
	if calls != 1 {
		t.Fatalf("calls = %d after a spent budget, want 1", calls)
	}

	retryAgentRequest(context.Background(), r, func() (string, error) { return "ok", nil })
	calls = 0
	retryAgentRequest(context.Background(), r, count(fail))
	if calls != turnRetryBudget {
		t.Fatalf("calls = %d after a success, want the full budget again", calls)
	}
}

func TestAgentRetryStopsOnCancel(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	retrySleep = func(context.Context, time.Duration) error { cancel(); return context.Canceled }
	t.Cleanup(func() { retrySleep = sleepCtx })
	calls := 0
	_, err := retryAgentRequest(ctx, &agentRetrier{}, func() (string, error) {
		calls++
		return "", errors.New("status 429")
	})
	if !errors.Is(err, context.Canceled) || calls != 1 {
		t.Fatalf("calls = %d, err = %v; cancelling must stop the wait", calls, err)
	}
}

type fakeStreamLLM struct{ rateLimitLLM }

func (f *fakeStreamLLM) CreateChatCompletionStream(ctx context.Context, req openai.ChatCompletionRequest) (<-chan cogito.StreamEvent, error) {
	return nil, nil
}

func TestRetryForAgentKeepsStreaming(t *testing.T) {
	if _, ok := retryForAgent(&fakeStreamLLM{}, nil).(cogito.StreamingLLM); !ok {
		t.Fatal("the wrapper hid streaming; cogito would fall back to blocking requests")
	}
	if _, ok := retryForAgent(&rateLimitLLM{}, nil).(cogito.StreamingLLM); ok {
		t.Fatal("the wrapper claimed streaming for a client without it")
	}
}

func TestRetryForAgentRetriesCompletions(t *testing.T) {
	stubRetrySleep(t)
	llm := &rateLimitLLM{failures: 3}
	_, _, err := retryForAgent(llm, nil).CreateChatCompletion(context.Background(), openai.ChatCompletionRequest{})
	if err != nil || llm.calls != 4 {
		t.Fatalf("calls = %d, err = %v; want 3 retries then success", llm.calls, err)
	}
}

// A sub-agent waiting on the backend is not stalled.
func TestStaleIgnoresBackendWaits(t *testing.T) {
	s := newStaleTestSession(true)
	s.agentLogs.started("a1", time.Now().Add(-2*staleAgentAfter))

	s.agentBackoff.waiting.Add(1)
	s.notifyStaleAgents(time.Now())
	if got := drainInjected(s); len(got) != 0 {
		t.Fatalf("an agent waiting on the backend was reported: %v", got)
	}

	// The wait ended just now: idleness counts from there.
	s.agentBackoff.lastEnd.Store(time.Now().UnixNano())
	s.agentBackoff.waiting.Add(-1)
	s.notifyStaleAgents(time.Now())
	if got := drainInjected(s); len(got) != 0 {
		t.Fatalf("reported right after the wait ended: %v", got)
	}
	s.notifyStaleAgents(time.Now().Add(staleAgentAfter + time.Second))
	if got := drainInjected(s); len(got) != 1 {
		t.Fatalf("notices = %v; a real stall after the wait must still be reported", got)
	}
}

package mcp

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/chromedp/cdproto/cdp"
	"github.com/chromedp/cdproto/dom"
	"github.com/chromedp/cdproto/input"
	"github.com/chromedp/cdproto/runtime"
	"github.com/chromedp/chromedp"
	"github.com/chromedp/chromedp/kb"
)

// pressAllowedKeys is the allowlist of key names accepted by browser_press,
// mapped to the corresponding github.com/chromedp/chromedp/kb control-rune
// constant. kb's named constants (kb.Enter, kb.Tab, ...) are strings holding
// the single Unicode "control" rune chromedp's key-encoding table maps back
// to the real Chrome DOM key (see kb.Keys) — that's what chromedp.KeyEvent
// expects, not a literal key name.
var pressAllowedKeys = map[string]string{
	"Enter":      kb.Enter,
	"Tab":        kb.Tab,
	"Escape":     kb.Escape,
	"ArrowUp":    kb.ArrowUp,
	"ArrowDown":  kb.ArrowDown,
	"ArrowLeft":  kb.ArrowLeft,
	"ArrowRight": kb.ArrowRight,
	"Backspace":  kb.Backspace,
	"Delete":     kb.Delete,
	"Home":       kb.Home,
	"End":        kb.End,
	"PageUp":     kb.PageUp,
	"PageDown":   kb.PageDown,
}

// keyForName maps an allowed browser_press key name to the kb control-rune
// string chromedp.KeyEvent expects. The error names the valid values so the
// model can retry with a correct one.
func keyForName(name string) (string, error) {
	if k, ok := pressAllowedKeys[name]; ok {
		return k, nil
	}
	return "", fmt.Errorf("browser_press: unsupported key %q — valid keys: Enter, Tab, Escape, ArrowUp, ArrowDown, ArrowLeft, ArrowRight, Backspace, Delete, Home, End, PageUp, PageDown", name)
}

const (
	pressSettleMaxProbes = 8 // ~1.2s ceiling for a triggered navigation to finish loading
	pressSettleNavGrace  = 2 // ~300ms to decide a key triggered NO navigation
	pressSettleInterval  = 150 * time.Millisecond
)

// settleAfterKey gives a key that may have triggered a native navigation
// (Enter submitting a form, Backspace on some SPAs, ...) a brief, bounded
// chance to actually kick off and finish loading before the caller
// re-snapshots. Without this the re-snapshot describes stale pre-navigation
// DOM: chromedp's key dispatch returns before the browser even starts the
// navigation, so at that instant the ORIGINAL document is still
// readyState=="complete" — an unconditional "is it complete?" check returns
// true on the page we're trying to leave (verified against a real Chrome: an
// immediate re-snapshot after chromedp.KeyEvent(kb.Enter) caught the old page,
// and a single readyState==complete check returned on it too).
//
// beforeURL is location.href captured BEFORE the key was dispatched. A
// navigating key changes the URL (or transiently tears down the JS execution
// context mid-load); we wait until the URL actually changes AND the new
// document reaches "complete". A key that navigates nowhere (arrows, Tab,
// Escape) never changes the URL, so once a short grace passes with no sign of
// navigation we return immediately rather than stalling the full ceiling.
// Best-effort throughout: a possibly-stale snapshot is a worse outcome than a
// broken tool call only in that the model can just re-snapshot.
func settleAfterKey(ctx context.Context, beforeURL string) {
	navSeen := false
	for probe := 0; probe < pressSettleMaxProbes; probe++ {
		select {
		case <-ctx.Done():
			return
		case <-time.After(pressSettleInterval):
		}
		var href, readyState string
		if err := chromedp.Run(ctx,
			chromedp.Evaluate("location.href", &href),
			chromedp.Evaluate("document.readyState", &readyState),
		); err != nil {
			navSeen = true // execution context torn down => a navigation is underway
			continue
		}
		if href != beforeURL {
			navSeen = true
			if readyState == "complete" {
				return // navigation committed and the new document finished loading
			}
			continue // navigation in flight; wait for the new document to load
		}
		// Still on the original document. If nothing has hinted at a navigation
		// within the grace window, the key was a no-op (arrow/Tab/Escape) — return
		// rather than stalling to the ceiling. Enter's form submit commits (URL
		// change or context teardown) well inside this window.
		if readyState == "complete" && !navSeen && probe+1 >= pressSettleNavGrace {
			return
		}
	}
}

// browserImplicitSubmitJS reproduces the browser's default action for Enter in
// a focused form field: submit the form the active element belongs to. Returns
// "submitted" when it did, else "noform"/"noactive". requestSubmit (not the
// bare .submit()) is used so the submit event fires and constraint validation
// runs — exactly like a real Enter, so an onsubmit that preventDefaults still
// wins and a form with unfilled required fields is not submitted.
const browserImplicitSubmitJS = `(function(){
	var e=document.activeElement; if(!e) return 'noactive';
	var f=e.form; if(!f) return 'noform';
	if(f.requestSubmit){ f.requestSubmit(); } else { f.submit(); }
	return 'submitted';
})()`

// scrollDelta maps an allowed browser_scroll direction to the JS expression
// used as the y argument of window.scrollBy — positive (down the page) or
// negative (up the page) 90% of the viewport height, so one scroll leaves a
// little overlap with the previous view. The error names the valid values so
// the model can retry with a correct one.
func scrollDelta(direction string) (string, error) {
	switch direction {
	case "down":
		return "window.innerHeight*0.9", nil
	case "up":
		return "-window.innerHeight*0.9", nil
	default:
		return "", fmt.Errorf("browser_scroll: unsupported direction %q — valid directions: up, down", direction)
	}
}

// cdpBackend converts a plain backend-node id (as stored in b.refs) to the
// cdproto type the DOM domain expects.
func cdpBackend(id int64) cdp.BackendNodeID { return cdp.BackendNodeID(id) }

// resolveRef looks up a snapshot ref (e.g. "@e5") in the most recent
// snapshot's ref map. Refs are per-snapshot: once a new browser_snapshot (or
// any tool that re-snapshots) runs, the old refs are gone.
func (b *browserServer) resolveRef(ref string) (int64, error) {
	ref = strings.TrimSpace(ref)
	b.mu.Lock()
	id, ok := b.refs[ref]
	b.mu.Unlock()
	if !ok {
		return 0, fmt.Errorf("unknown ref %q — take a fresh browser_snapshot; refs change each snapshot", ref)
	}
	return id, nil
}

// clickBackendNode resolves a backend DOM node to a JS handle, scrolls it into
// view, and clicks it via the DOM — the reliable path (a synthesized coordinate
// click can miss on scroll/overlay).
func (b *browserServer) clickBackendNode(ctx context.Context, backendID int64) error {
	return chromedp.Run(ctx, chromedp.ActionFunc(func(ctx context.Context) error {
		obj, err := dom.ResolveNode().WithBackendNodeID(cdpBackend(backendID)).Do(ctx)
		if err != nil {
			return err
		}
		_, exc, err := runtime.CallFunctionOn(
			`function(){ this.scrollIntoView({block:"center"}); this.click(); return true; }`).
			WithObjectID(obj.ObjectID).WithReturnByValue(true).Do(ctx)
		if err != nil {
			return err
		}
		if exc != nil {
			return fmt.Errorf("click JS error: %s", exc.Text)
		}
		return nil
	}))
}

// typeIntoBackendNode resolves a backend DOM node, focuses it and clears any
// existing value, then inserts text via a real CDP input event
// (input.InsertText) so the DOM/renderer actually observes the keystrokes —
// unlike the accessibility path, which never reaches the DOM.
func (b *browserServer) typeIntoBackendNode(ctx context.Context, backendID int64, text string) error {
	return chromedp.Run(ctx, chromedp.ActionFunc(func(ctx context.Context) error {
		obj, err := dom.ResolveNode().WithBackendNodeID(cdpBackend(backendID)).Do(ctx)
		if err != nil {
			return err
		}
		// Focus + clear existing value via the element handle. Form controls
		// (input/textarea) hold their text in .value; a contenteditable
		// element (AX role "textbox" but no .value) needs its textContent
		// cleared instead, or InsertText below just appends to what's there.
		if _, exc, err := runtime.CallFunctionOn(
			`function(){ this.focus(); if('value' in this){ this.value=''; } else if(this.isContentEditable){ this.textContent=''; } this.dispatchEvent(new Event('input',{bubbles:true})); return true; }`).
			WithObjectID(obj.ObjectID).WithReturnByValue(true).Do(ctx); err != nil {
			return err
		} else if exc != nil {
			return fmt.Errorf("focus JS error: %s", exc.Text)
		}
		// Insert text as a real CDP input event so the DOM/renderer observes it
		// (unlike the AX path that never reaches the DOM).
		return input.InsertText(text).Do(ctx)
	}))
}

