	if m.pastePanel.text != before || !strings.Contains(m.hint, "clipboard unavailable") {
		t.Fatal("modal clipboard error not retained")
	}
	m = update(m, tea.KeyMsg{Type: tea.KeyEsc})
	before = m.draft.Expanded()
	next, cmd = m.Update(tea.KeyMsg{Type: tea.KeyCtrlV})
	m = next.(Model)
	m = update(m, cmd())
	if m.draft.Expanded() != before || !strings.Contains(m.hint, "clipboard unavailable") {
		t.Fatal("clipboard error not retained")
	}
}

func TestComposerAggregateSmallPastes(t *testing.T) {
	m := newQueueTestModel()
	m.loading = true
	// Equivalent to 10,000 small paste insertions without quadratic test setup.
	snapshot := draftSnapshot{NextID: 10001}
	for i := 1; i <= 10000; i++ {
		snapshot.Segments = append(snapshot.Segments, draftSegmentSnapshot{uint64(i), draftText, "a\n"})
	}
	if err := m.draft.Restore(snapshot); err != nil {
		t.Fatal(err)
	}
	m.projectDraft(len(m.draft.Projection().Text))
	want := strings.Repeat("a\n", 10000)
	if m.textarea.Value() != m.draft.Projection().Text {
		t.Fatal("projection clipped by textarea")
	}
	m = update(m, tea.WindowSizeMsg{Width: 80, Height: 24})
	m = update(m, tea.KeyMsg{Type: tea.KeyLeft})
	m = update(m, tea.KeyMsg{Type: tea.KeyEnd})
	m = composerPaste(m, "tail\t\r\n")
	want += "tail\t\r\n"
	if m.draft.Expanded() != want {
		t.Fatal("aggregate update lost payload")
	}
	m = update(m, tea.KeyMsg{Type: tea.KeyEnter})
	if len(m.queue) != 1 || m.queue[0].text != want {
		t.Fatal("aggregate send lost payload")
	}
	m = update(m, tea.KeyMsg{Type: tea.KeyCtrlE})
	m = update(m, tea.WindowSizeMsg{Width: 120, Height: 40})
	if m.draft.Expanded() != want {
		t.Fatal("aggregate recovery lost payload")
	}
}

func TestComposerInlineCaseKeysPreserveSource(t *testing.T) {
	for _, separator := range []string{"\t", "\r", "␉", "␍", "\t␉\r␍"} {
		for _, tc := range []struct{ key, input, changed string }{
			{"u", "a%sb", "A%sB"},
			{"l", "A%sB", "a%sb"},
			{"c", "a%sb", "A%sb"},
		} {
			t.Run(tc.key+"/"+separator, func(t *testing.T) {
				payload := strings.ReplaceAll(tc.input, "%s", separator)
				want := strings.ReplaceAll(tc.changed, "%s", separator)
				// Multi-rune replacements spanning projected controls are rejected.
				// Capitalization only changes the initial rune and remains safe.
				if tc.key != "c" && strings.ContainsAny(separator, "\t\r") {
					want = payload
				}
				m := newQueueTestModel()
				m.loading = true
				m = composerPaste(m, payload)
				m = update(m, tea.KeyMsg{Type: tea.KeyHome})
				m = update(m, tea.KeyMsg{Type: tea.KeyRunes, Alt: true, Runes: []rune(tc.key)})
				if got := m.draft.Expanded(); got != want {
					t.Fatalf("case key corrupted source: got %q, want %q", got, want)
				}
				m = update(m, tea.KeyMsg{Type: tea.KeyEnter})
				if len(m.queue) != 1 || m.queue[0].text != want {
					t.Fatalf("queue source: %q, want %q", m.queue, want)
				}
			})
		}
	}
}

func TestComposerTypingAndDeletionAroundInlineTab(t *testing.T) {
	m := newQueueTestModel()
	m = composerPaste(m, "a\tb␉")
	m = update(m, tea.KeyMsg{Type: tea.KeyHome})
	m = update(m, tea.KeyMsg{Type: tea.KeyRight})
	m = composerKey(m, "x")
	m = update(m, tea.KeyMsg{Type: tea.KeyRight})
	m = composerKey(m, "y")
	if got := m.draft.Expanded(); got != "ax\tyb␉" {
		t.Fatalf("typing around tab: %q", got)
	}
	m = update(m, tea.KeyMsg{Type: tea.KeyBackspace})
	m = update(m, tea.KeyMsg{Type: tea.KeyBackspace})
	if got := m.draft.Expanded(); got != "axb␉" {
		t.Fatalf("deleting tab: %q", got)
	}
}

